create procedure ME_ConsultarMatrizPorOferta --14072	@IdPedido INT,	/*--------------------parametros contrato  --------------------*/    @IdContrato    INT = null,    @IdUsuario     INT = null,    @FechaRegistro DATETIME = null	/*-------------------------------------------------------------*/ASBEGIN		DECLARE @PorcEvaluacionG INT,			@PorcEvaluacionT int	SET @PorcEvaluacionG = (SELECT Ponderacion FROM dbo.ME_TiposMatriz WHERE IdTipoEvaluacion = 2)	SET @PorcEvaluacionT = (SELECT Ponderacion FROM dbo.ME_TiposMatriz WHERE IdTipoEvaluacion = 1)	SELECT m.IdDocMatriz, 			m.NombreDoc,			me.Nombre,			m.PorcentajeET, 			m.PorcentajeEC,			@PorcEvaluacionG,			@PorcEvaluacionT		FROM dbo.TA_DocMatrizOperacion m			left JOIN dbo.ME_MatrizEvaluacion me ON me.IdMatrizEvaluacion = CAST(m.NombreDoc AS INT)		WHERE m.IdOperacion = @IdPedidoEND